import re

output_path = '/root/training_feedback_ready.hwpx'

with zipfile.ZipFile(output_path, 'r') as zf:
    for info in zf.infolist():
        if info.filename.endswith('.xml'):
            content = zf.read(info.filename).decode('utf-8')
            print(f"=== {info.filename} ===")

            # Find and print all text content between <hp:t> tags
            text_matches = re.findall(r'<hp:t>([^<]+)</hp:t>', content)
            for text in text_matches:
                print(f"  Text: {text}")

            # Check for the specific values we transformed
            if '참석자' in content:
                match = re.search(r'참석자[^:]*:\s*([^<]+)', content)
                if match:
                    print(f"  -> 참석자수 value: '{match.group(1)}'")

            if '만족도' in content:
                match = re.search(r'만족도[^:]*:\s*([^<]+)', content)
                if match:
                    print(f"  -> 만족도 value: '{match.group(1)}'")

            if '종합의견' in content:
                match = re.search(r'종합의견[^:]*:\s*([^<]+)', content)
                if match:
                    print(f"  -> 종합의견 value: '{match.group(1)}'")

            print()"}

